package com.alyshapursley.punctuowlity;
import android.os.Bundle;import android.util.Patterns;import android.widget.EditText;import android.widget.Switch;import android.widget.Toast;import androidx.appcompat.app.AppCompatActivity;
public final class AccountActivity extends AppCompatActivity{
 private DatabaseHelper db;private EditText first,last,email,phone,username;private Switch sms;private String original;
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_account);db=new DatabaseHelper(this);first=findViewById(R.id.edit_first_name);last=findViewById(R.id.edit_last_name);email=findViewById(R.id.edit_email);phone=findViewById(R.id.edit_phone);username=findViewById(R.id.edit_username);sms=findViewById(R.id.switch_sms);original=getSharedPreferences(SmsReminderReceiver.PREFERENCES_NAME,MODE_PRIVATE).getString(LoginActivity.CURRENT_USERNAME,"");String[] p=db.getUserProfile(original);if(p==null){finish();return;}first.setText(p[0]);last.setText(p[1]);email.setText(p[2]);phone.setText(p[3]);username.setText(p[4]);sms.setChecked(getSharedPreferences(SmsReminderReceiver.PREFERENCES_NAME,MODE_PRIVATE).getBoolean(SmsReminderReceiver.SMS_ENABLED,false));findViewById(R.id.button_back).setOnClickListener(v->finish());findViewById(R.id.button_save).setOnClickListener(v->save());}
 private void save(){String f=first.getText().toString().trim(),l=last.getText().toString().trim(),e=email.getText().toString().trim(),p=phone.getText().toString().trim(),u=username.getText().toString().trim();if(f.isEmpty()||l.isEmpty()||e.isEmpty()||u.isEmpty()||!Patterns.EMAIL_ADDRESS.matcher(e).matches()){Toast.makeText(this,"Enter valid required account information",Toast.LENGTH_SHORT).show();return;}if(!p.isEmpty()&&!Patterns.PHONE.matcher(p).matches()){Toast.makeText(this,"Enter a valid phone number",Toast.LENGTH_SHORT).show();return;}if(!db.updateUserProfile(original,f,l,e,p,u)){Toast.makeText(this,"Unable to update account. That username may already be used.",Toast.LENGTH_LONG).show();return;}original=u;boolean enable=sms.isChecked()&&!p.isEmpty();getSharedPreferences(SmsReminderReceiver.PREFERENCES_NAME,MODE_PRIVATE).edit().putString(LoginActivity.CURRENT_USERNAME,u).putString(SmsReminderReceiver.SMS_PHONE_NUMBER,p).putBoolean(SmsReminderReceiver.SMS_ENABLED,enable).apply();Toast.makeText(this,"Account updated",Toast.LENGTH_SHORT).show();}
}
